<template><view class="page"><view class="nav" :style="{height:`${navHeight}rpx`}"><view @click="back">‹</view><text>确认订单</text></view><scroll-view scroll-y class="scroll" :style="{paddingTop:`${navHeight}rpx`}"><view class="address" @click="chooseAddress"><view class="address-icon">≡</view><view v-if="address" class="address-content"><view><text>{{address.name}}</text><text class="ui-small">{{address.phone}}</text></view><text class="ui-small">{{fullAddress}}</text></view><text v-else class="placeholder">请添加收货地址</text><view class="arrow">›</view></view><view v-if="product" class="product-section"><view class="product-card"><image :src="product.cover_image||'/static/navigation/sravx-mark.png'" mode="aspectFill"/><view><text>{{product.name}}</text><text class="ui-small">{{product.selectedColor?(isPointsOrder?'':`型号：${product.selectedModel||'--'}；颜色：${product.selectedColor}`):(product.spec||'默认规格')}}</text><text v-if="product.protectSelected" class="ui-small">已选 SRAVX Protect{{product.protectDisplayOnly?'（当前仅展示）':''}}</text><text class="ui-strong">{{isPointsOrder?`${product.price} 积分`:`¥${orderAmount}`}}</text><view class="qty"><view :class="{disabled:quantity<=1}" @click="decrease">−</view><text>{{quantity}}</text><view @click="increase">＋</view></view></view></view></view><view v-if="!isPointsOrder&&!usesStructuredCheckout&&product&&product.allow_coupon!==0" class="row" @click="openCoupons"><text>优惠券</text><view v-if="selectedCoupon" class="coupon-selected"><text class="ui-small">减¥{{selectedCoupon.value}}</text><text>{{selectedCoupon.name}}</text><view @click.stop="removeCoupon">×</view></view><text class="ui-small" v-else>{{coupons.length?`${coupons.length}张可用`:'暂无可用'}}</text><view class="arrow">›</view></view><view v-if="!isPointsOrder&&!usesStructuredCheckout&&product&&product.allow_coupon===0" class="row disabled"><text>优惠券</text><text class="ui-small">此商品无法使用优惠券</text></view><view class="row"><text>订单备注</text><input v-model="remark" placeholder="选填，可备注特殊需求" maxlength="100"/></view><view class="summary"><view><text class="ui-small">商品金额</text><text>{{isPointsOrder?`${orderAmount} 积分`:`¥${orderAmount}`}}</text></view><view v-if="isPointsOrder&&cashAmount!=='0.00'"><text class="ui-small">现金补差</text><text>¥{{cashAmount}}</text></view><view v-if="!isPointsOrder&&!usesStructuredCheckout&&Number(couponDiscount)>0"><text class="ui-small">优惠券</text><text class="discount">-¥{{couponDiscount}}</text></view><view v-if="!isPointsOrder"><text class="ui-small">运费</text><text>¥0.00</text></view></view><view class="bottom-space"/></scroll-view><view v-if="couponPopupVisible" class="mask" @click="couponPopupVisible=false"><view class="coupon-panel" @click.stop><view class="coupon-head"><text>选择优惠券</text><text class="ui-small">共{{coupons.length}}张可用</text></view><scroll-view scroll-y class="coupon-list"><view v-for="item in coupons" :key="item.id" class="coupon" :class="{picked:pendingCoupon&&pendingCoupon.id===item.id}" @click="pendingCoupon=item"><view><text class="ui-small">满减券</text><text class="ui-strong">¥{{item.value}}</text><text class="ui-small">满{{item.min_amount}}可用</text></view><view><text>{{item.name}}</text><text class="ui-small">{{item.popupDesc}}</text><text class="ui-small">{{item.popupDate}}</text></view></view></scroll-view><view class="coupon-actions"><view @click="clearCoupon">不使用</view><view @click="confirmCoupon">确认使用</view></view></view></view><view class="bottom"><view><text class="ui-small">合计</text><text class="ui-strong">{{isPointsOrder?(cashAmount!=='0.00'?`${finalAmount} 积分 + ¥${cashAmount}`:`${finalAmount} 积分`):`¥${finalAmount}`}}</text></view><view :class="{submitting}" @click="submit">{{isPointsOrder&&cashAmount!=='0.00'?'提交并支付':'提交订单'}}</view></view></view></template>
<script>import api from '../../common/api.js';function date(input){return input?String(input).replace('T',' ').slice(0,10).replace(/-/g,'.'):'--'}export default{data(){return{product:null,address:null,coupons:[],selectedCoupon:null,pendingCoupon:null,couponPopupVisible:false,remark:'',navHeight:96,isPointsOrder:false,orderAmount:'0',cashAmount:'0.00',couponDiscount:'0.00',finalAmount:'0',submitting:false,quote:null}},computed:{quantity(){return Math.max(1,Number(this.product&&this.product.quantity)||1)},fullAddress(){const a=this.address||{};return`${a.province||''}${a.city||''}${a.district||''}${a.detail||a.address||''}`},usesStructuredCheckout(){return!this.isPointsOrder&&api.structuredCheckoutEnabled()&&Number(this.product&&this.product.skuId)>0}},onLoad(query){this.initNav();this.isPointsOrder=query.isPointsOrder==='true';if(query.productData){try{this.product=JSON.parse(decodeURIComponent(query.productData));this.recalculate();if(this.usesStructuredCheckout)this.refreshQuote()}catch(error){uni.showToast({title:'数据加载失败',icon:'none'})}}this.loadAddress();if(!this.isPointsOrder&&!this.usesStructuredCheckout&&this.product&&this.product.allow_coupon!==0)this.loadCoupons()},onShow(){const selected=uni.getStorageSync('sravx_selected_address');if(selected){this.address=selected;uni.removeStorageSync('sravx_selected_address')}},methods:{initNav(){try{const menu=uni.getMenuButtonBoundingClientRect(),sys=uni.getSystemInfoSync();this.navHeight=Math.ceil((menu.bottom+8)*750/sys.screenWidth)}catch(error){}},async loadAddress(){try{const list=api.asList(await api.getAddressList());this.address=list.find(item=>Number(item.is_default)===1)||list[0]||null}catch(error){}},async loadCoupons(){try{const list=api.asList(await api.getAvailableCoupons());const amount=Number(this.product.price)*this.quantity;this.coupons=list.filter(item=>amount>=(Number(item.min_amount)||0)).map(item=>({...item,popupDesc:item.usage_note||item.desc||'全场可用',popupDate:`${date(item.start_time)} - ${date(item.expire_time)}`}))}catch(error){}},applyQuote(quote){this.quote=quote;this.orderAmount=(Number(quote.productAmountFen||0)/100).toFixed(2);this.couponDiscount='0.00';this.finalAmount=(Number(quote.payableAmountFen||0)/100).toFixed(2)},async refreshQuote(){if(!this.usesStructuredCheckout)return null;const quote=await api.createCheckoutQuote({skuId:Number(this.product.skuId),quantity:this.quantity,protectOfferId:this.product.protectSelected&&Number(this.product.protectOfferId)>0?Number(this.product.protectOfferId):undefined});this.applyQuote(quote);return quote},recalculate(){if(!this.product)return;const amount=Number(this.product.price)*this.quantity;if(this.isPointsOrder){this.orderAmount=String(amount);this.cashAmount=(Number(this.product.supportMixedPay?this.product.cashPrice:0)*this.quantity).toFixed(2);this.couponDiscount='0.00';this.finalAmount=String(amount);return}const discount=this.selectedCoupon?Number(this.selectedCoupon.value)||0:0;this.orderAmount=amount.toFixed(2);this.couponDiscount=discount.toFixed(2);this.finalAmount=Math.max(0,amount-discount).toFixed(2)},back(){uni.navigateBack()},chooseAddress(){uni.navigateTo({url:`/pages/address-manage/index?from=confirmOrder&selectedId=${this.address?this.address.id:''}`})},openCoupons(){if(!this.coupons.length){uni.showToast({title:'暂无可用优惠券',icon:'none'});return}this.pendingCoupon=this.selectedCoupon;this.couponPopupVisible=true},removeCoupon(){this.selectedCoupon=null;this.recalculate()},confirmCoupon(){this.selectedCoupon=this.pendingCoupon||null;this.couponPopupVisible=false;this.recalculate()},clearCoupon(){this.pendingCoupon=null;this.selectedCoupon=null;this.couponPopupVisible=false;this.recalculate()},decrease(){if(this.quantity<=1)return;this.product={...this.product,quantity:this.quantity-1};if(this.usesStructuredCheckout)this.refreshQuote().catch(()=>{});else if(!this.isPointsOrder)this.loadCoupons();this.recalculate()},increase(){this.product={...this.product,quantity:this.quantity+1};if(this.usesStructuredCheckout)this.refreshQuote().catch(()=>{});else if(!this.isPointsOrder)this.loadCoupons();this.recalculate()},async pay(params){return new Promise((resolve,reject)=>uni.requestPayment({...params,signType:params.signType||'RSA',success:resolve,fail:reject}))},async submit(){if(!this.address)return uni.showToast({title:'请选择收货地址',icon:'none'});if(!this.product)return uni.showToast({title:'商品信息异常',icon:'none'});if(this.submitting)return;this.submitting=true;try{if(this.isPointsOrder){const result=await api.createPointsOrder({pointsProductId:this.product.id,addressId:this.address.id,quantity:this.quantity,selectedSpecName:this.product.selectedColor||'',remark:this.remark});if(result.needCashPayment){const pay=await api.createPaymentOrder({orderId:result.orderId,orderType:'points',description:this.product.name||'Sravx 积分订单'});await this.pay(pay)}uni.showToast({title:'兑换成功',icon:'success'});setTimeout(()=>uni.redirectTo({url:`/pages/points-order-detail/index?id=${result.orderId||result.orderNo}`}),1200);return}if(this.usesStructuredCheckout){const quote=await this.refreshQuote();const order=await api.createOrder({quoteId:quote.quoteId,addressId:this.address.id,remark:this.remark});if(!order||!order.orderId)throw new Error('订单创建失败');const pay=await api.createPaymentOrder({orderId:order.orderId,backend:'target',description:this.product.name||'Sravx 商品订单'});if(!pay.paid)await this.pay(pay);uni.showToast({title:'支付成功',icon:'success'});setTimeout(()=>uni.reLaunch({url:'/pages/order-list/index'}),1200);return}const coupon=this.selectedCoupon&&(this.selectedCoupon.user_coupon_id||this.selectedCoupon.userCouponId||this.selectedCoupon.id);const order=await api.createOrder({addressId:this.address.id,productId:this.product.id,quantity:this.quantity,selectedColor:this.product.selectedColor||'',couponId:coupon||null,remark:this.remark});if(!order||!order.orderId)throw new Error('订单创建失败');const pay=await api.createPaymentOrder({orderId:order.orderId,description:this.product.name||'Sravx 商品订单'});if(!pay.paid)await this.pay(pay);uni.showToast({title:'支付成功',icon:'success'});setTimeout(()=>uni.reLaunch({url:'/pages/order-list/index'}),1200)}catch(error){const message=error.errMsg||error.message||'操作失败';if(message.includes('requestPayment:fail cancel')||message.includes('-2'))uni.showToast({title:'已取消支付，订单保留',icon:'none'});else if(message.includes('requestPayment:fail'))uni.showModal({title:'支付提示',content:'订单已创建，但支付未完成。可在“我的订单”中继续支付。',confirmText:'去订单',success:r=>{if(r.confirm)uni.reLaunch({url:'/pages/order-list/index'})}});else uni.showToast({title:message,icon:'none'})}finally{this.submitting=false}}}}</script>
<style>.page,.scroll{height:100%;background:#F4F6F8}.nav{position:fixed;top:0;left:0;right:0;z-index:5;display:flex;align-items:flex-end;padding:0 24rpx 12rpx;background:rgba(245,245,247,.88)}.nav view{width:64rpx;font-size:52rpx}.nav text{flex:1;margin-right:64rpx;text-align:center;font-size:34rpx;font-weight:600}.address,.row,.product-section,.summary{margin:20rpx 20rpx 16rpx;border-radius:28rpx;background:#fff}.address{display:flex;align-items:center;padding:32rpx}.address-icon{width:36rpx;height:36rpx;margin-right:24rpx;border:3rpx solid #0B0D10;border-radius:50%;color:#0B0D10;text-align:center}.address-content{flex:1;display:flex;flex-direction:column;gap:8rpx}.address-content view{display:flex;gap:16rpx}.address-content text{font-size:30rpx;font-weight:600}.address-content .ui-small,.placeholder,.row .ui-small{font-size:26rpx;color:#636366}.placeholder{flex:1}.arrow{margin-left:16rpx;font-size:32rpx;color:#c7c7cc}.product-section{padding:24rpx 32rpx}.product-card{padding:24rpx;display:flex;border-radius:20rpx;background:#F4F6F8}.product-card>image{width:180rpx;height:180rpx;border-radius:12rpx;background:#fff}.product-card>view{min-height:180rpx;flex:1;margin-left:24rpx;display:flex;flex-direction:column;gap:12rpx}.product-card text{font-size:30rpx;font-weight:600}.product-card .ui-small{font-size:24rpx;color:#636366}.product-card .ui-strong{margin-top:auto;font-size:32rpx;color:#0B0D10}.qty{display:flex;align-items:center;gap:12rpx}.qty view{width:48rpx;height:48rpx;line-height:48rpx;text-align:center;border:1rpx solid #e5e5ea;border-radius:10rpx;background:#fff;font-size:30rpx}.qty .disabled{opacity:.4}.qty text{min-width:52rpx;text-align:center;font-size:26rpx}.row{display:flex;align-items:center;padding:28rpx 32rpx}.row>text{width:140rpx;font-size:28rpx;font-weight:500}.row>input{flex:1;text-align:right;font-size:28rpx}.row>.ui-small{flex:1;text-align:right}.disabled{opacity:.55}.coupon-selected{display:flex;flex:1;align-items:center;justify-content:flex-end;gap:10rpx;overflow:hidden}.coupon-selected .ui-small{padding:6rpx 12rpx;border-radius:8rpx;background:#E9EDF2;color:#0B0D10;font-size:20rpx}.coupon-selected text{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:24rpx}.coupon-selected view{width:34rpx;height:34rpx;line-height:34rpx;text-align:center;border-radius:50%;background:#f3f4f6;color:#9ca3af}.summary{padding:24rpx 32rpx}.summary view{display:flex;justify-content:space-between;padding:12rpx 0}.summary .ui-small{font-size:26rpx;color:#636366}.summary text{font-size:26rpx}.discount{color:#4A4A4D}.bottom-space{height:180rpx}.bottom{position:fixed;bottom:0;left:0;right:0;z-index:5;display:flex;align-items:center;padding:16rpx 32rpx calc(16rpx + env(safe-area-inset-bottom));background:rgba(255,255,255,.95)}.bottom>view:first-child{flex:1;display:flex;align-items:baseline;gap:8rpx}.bottom .ui-small{font-size:26rpx;color:#636366}.bottom .ui-strong{font-size:36rpx;color:#0B0D10}.bottom>view:last-child{width:220rpx;height:84rpx;line-height:84rpx;text-align:center;border-radius:42rpx;background:#0B0D10;color:#fff;font-size:30rpx;font-weight:600}.bottom>view.submitting{opacity:.55}.mask{position:fixed;inset:0;z-index:10;display:flex;align-items:flex-end;background:rgba(0,0,0,.42)}.coupon-panel{width:100%;max-height:72vh;padding:20rpx 20rpx calc(20rpx + env(safe-area-inset-bottom));border-radius:24rpx 24rpx 0 0;background:#fff}.coupon-head{display:flex;justify-content:space-between;padding:6rpx 6rpx 12rpx}.coupon-head text{font-size:32rpx;font-weight:600}.coupon-head .ui-small{font-size:24rpx;color:#636366}.coupon-list{max-height:48vh}.coupon{display:flex;margin-bottom:12rpx;overflow:hidden;border:2rpx solid transparent;border-radius:16rpx;background:#f7f8fa}.coupon.picked{border-color:#0B0D10}.coupon>view:first-child{width:150rpx;padding:8rpx;display:flex;flex-direction:column;align-items:center;justify-content:center;background:#0B0D10;color:#fff}.coupon>view:first-child .ui-strong{font-size:36rpx}.coupon .ui-small{font-size:18rpx}.coupon>view:last-child{flex:1;padding:10rpx;display:flex;flex-direction:column;gap:2rpx}.coupon>view:last-child text{font-size:26rpx;font-weight:600}.coupon>view:last-child .ui-small{color:#636366}.coupon-actions{display:flex;gap:14rpx;margin-top:6rpx}.coupon-actions view{flex:1;height:74rpx;line-height:74rpx;text-align:center;border-radius:99rpx;background:#f3f4f6;font-size:28rpx;font-weight:600}.coupon-actions view:last-child{background:#0B0D10;color:#fff}</style>
